BEGIN TRANSACTION;
CREATE TABLE equations(id TEXT PRIMARY KEY,label TEXT,ascii TEXT,latex TEXT,status TEXT);
CREATE TABLE meta(key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE objects(id TEXT PRIMARY KEY,name TEXT,symbol TEXT,kind TEXT,status TEXT,definition TEXT);
CREATE TABLE open_questions(id TEXT PRIMARY KEY,question TEXT,status TEXT,blocks TEXT);
CREATE TABLE package_files(path TEXT PRIMARY KEY,sha256 TEXT,bytes INTEGER,role TEXT);
CREATE TABLE qmo_addresses(qmo_id TEXT PRIMARY KEY,uri TEXT UNIQUE,canonical_name TEXT,object_id TEXT,status TEXT,summary TEXT,
 FOREIGN KEY(object_id) REFERENCES objects(id));
CREATE TABLE qmo_aliases(alias TEXT,qmo_id TEXT,PRIMARY KEY(alias,qmo_id),
 FOREIGN KEY(qmo_id) REFERENCES qmo_addresses(qmo_id));
CREATE TABLE qmo_bindings(binding_id TEXT PRIMARY KEY,qmo_id TEXT,binding_type TEXT,binding_key TEXT,note TEXT,
 FOREIGN KEY(qmo_id) REFERENCES qmo_addresses(qmo_id));
CREATE TABLE qmo_edges(edge_id TEXT PRIMARY KEY,source_qmo_id TEXT,relation TEXT,target_qmo_id TEXT,status TEXT,
 FOREIGN KEY(source_qmo_id) REFERENCES qmo_addresses(qmo_id),
 FOREIGN KEY(target_qmo_id) REFERENCES qmo_addresses(qmo_id));
CREATE TABLE relations(id TEXT PRIMARY KEY,source TEXT,relation TEXT,target TEXT,status TEXT,
 FOREIGN KEY(source) REFERENCES objects(id), FOREIGN KEY(target) REFERENCES objects(id));
CREATE TABLE roadmap_steps(id TEXT PRIMARY KEY,ordinal INTEGER,title TEXT,verdict TEXT);
PRAGMA writable_schema=ON;
CREATE TABLE 'search_fts_config'(k PRIMARY KEY, v) WITHOUT ROWID;
CREATE TABLE 'search_fts_content'(id INTEGER PRIMARY KEY, c0, c1, c2, c3, c4);
CREATE TABLE 'search_fts_data'(id INTEGER PRIMARY KEY, block BLOB);
CREATE TABLE 'search_fts_docsize'(id INTEGER PRIMARY KEY, sz BLOB);
CREATE TABLE 'search_fts_idx'(segid, term, pgno, PRIMARY KEY(segid, term)) WITHOUT ROWID;
CREATE TABLE source_files(file TEXT PRIMARY KEY,sha256 TEXT,bytes INTEGER,embedded INTEGER,role TEXT);
PRAGMA writable_schema=OFF;
COMMIT;
